import { useEffect, useState } from "react";

import api from "../api";

import socket from "../socket";

import { useToast } from "../context/ToastContext";

import Skeleton from "../components/Skeleton";

import "../components/skeleton.css";

export default function ProviderDashboard() {

  const [bookings, setBookings] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const [activeSession, setActiveSession] = useState(null);
  const [history, setHistory] = useState([]);

  const { addToast } = useToast();

  // ======================================
  // GET TOKEN
  // ======================================

  const token =
    localStorage.getItem("token");

  // ======================================
  // FETCH BOOKINGS
  // ======================================

  const fetchBookings = async () => {

    try {

      setLoading(true);

      const res =
        await api.get(
          "/bookings/provider-bookings"
        );

      console.log(
        "Provider bookings:",
        res.data
      );

      setBookings(res.data || []);

    } catch (err) {

      console.log(err);

      addToast(
        "Unable to load bookings",
        "error"
      );

    } finally {

      setLoading(false);

    }

  };

  // ======================================
  // SOCKET
  // ======================================

  useEffect(() => {

    if (token) {

      socket.emit("register", {
        token
      });

    }

    fetchBookings();

    socket.on(
      "booking-created",
      (data) => {

        console.log(
          "Realtime booking:",
          data
        );

        addToast(
          `New Booking: ${data.booking.serviceName}`,
          "success"
        );

        fetchBookings();

      }
    );

    socket.on(
      "booking-update",
      () => {

        fetchBookings();

      }
    );

    return () => {

      socket.off(
        "booking-created"
      );

      socket.off(
        "booking-update"
      );

    };

  }, []);

  // ======================================
  // PROVIDER ACTION
  // ======================================

  const providerAction = async (
  bookingId,
  action
) => {

  try {

    const res =
      await api.put(

        `/bookings/provider-action/${bookingId}`,

        { action }

      );

    console.log(
      "Provider action response:",
      res.data
    );

    // =========================
    // REMOVE REJECTED BOOKINGS
    // =========================

    if (action === "reject") {

      setBookings((prev) =>

        prev.filter(

          (booking) =>

            booking._id !== bookingId

        )

      );

    }

    // =========================
    // UPDATE ACCEPTED BOOKING
    // =========================

    if (action === "accept") {

      setBookings((prev) =>

        prev.map((booking) =>

          booking._id === bookingId

            ? {
                ...booking,
                status: "accepted"
              }

            : booking

        )

      );
      if (res.data?.booking) setActiveSession(res.data.booking);

    }

    addToast(

      `Booking ${action}ed successfully`,

      "success"

    );

  } catch (err) {

    console.log(err);

    addToast(
      "Action failed",
      "error"
    );

  }

};

  // fetch provider history
  useEffect(() => {
    const fetchHistory = async () => {
      try {
        const res = await api.get('/bookings/provider-history');
        setHistory(res.data || []);
      } catch (err) {
        console.error('Unable to load provider history', err);
      }
    };
    fetchHistory();
  }, []);

  const completeWork = async (bookingId) => {
    try {
      const res = await api.put(`/bookings/complete/${bookingId}`);
      addToast('Marked work as completed', 'success');
      setBookings((prev) => prev.filter((b) => b._id !== bookingId));
      setActiveSession(null);
      // refresh history
      const h = await api.get('/bookings/provider-history');
      setHistory(h.data || []);
    } catch (err) {
      console.error(err);
      addToast('Unable to mark completed', 'error');
    }
  };

  // ======================================
  // ACTIVE BOOKINGS
  // ======================================

  const activeBookings =
  bookings.filter(

    (booking) =>

      booking.status !== "completed" &&
      booking.status !== "cancelled" &&
      booking.status !== "rejected"

  );
  // ======================================
  // UI
  // ======================================

  return (

    <div className="dashboard-container">

      <header className="dashboard-header">

        <div className="dashboard-logo">

          🚀 FastAid

        </div>

        <button

          className="logout-btn"

          onClick={() => {

            localStorage.removeItem(
              "token"
            );

            window.location.href = "/";

          }}

        >

          Logout

        </button>

      </header>

      <div className="dashboard-content">

        <h1 className="dashboard-title">

          Provider Dashboard 🛠️

        </h1>

        <p className="dashboard-subtitle">

          Manage your service requests

        </p>

        {/* ========================= */}
        {/* LOADING */}
        {/* ========================= */}

        {loading ? (

          <div style={{ marginTop: 20 }}>

            <Skeleton
              count={4}
              height="100px"
            />

          </div>

        ) : activeBookings.length === 0 ? (

          // =========================
          // NO BOOKINGS
          // =========================

          <div className="no-requests">

            <div className="no-requests-icon">
              🔔
            </div>

            <div className="no-requests-text">

              No active bookings

            </div>

          </div>

        ) : (

          // =========================
          // BOOKINGS LIST
          // =========================

          <div>
            {activeSession && (
              <div className="booking-card" style={{ background: '#fff', padding: 20, borderRadius: 16, marginBottom: 20, boxShadow: '0 6px 16px rgba(0,0,0,0.08)' }}>
                <h2>Active Session — {activeSession.serviceName}</h2>
                <p>👤 Customer: {activeSession.userId?.name}</p>
                <p>📍 Location: {activeSession.location || activeSession.locationDetails?.fullAddress}</p>
                <p>💰 Amount: ₹{activeSession.servicePrice}</p>
                <div style={{ display: 'flex', gap: 10, marginTop: 12 }}>
                  <button onClick={() => completeWork(activeSession._id)} style={{ background: '#2563EB', color: '#fff', border: 'none', padding: '10px 16px', borderRadius: 10, cursor: 'pointer' }}>Work Completed</button>
                  <button onClick={() => setActiveSession(null)} style={{ background: '#6B7280', color: '#fff', border: 'none', padding: '10px 16px', borderRadius: 10, cursor: 'pointer' }}>Close Session</button>
                </div>
              </div>
            )}

            <div className="booking-list">

            {activeBookings.map((booking) => {
              return (
                <div

                  key={booking._id}

                  className="booking-card"

                  style={{

                    background: "#fff",

                    padding: "20px",

                    borderRadius: "16px",

                    marginBottom: "20px",

                    boxShadow:
                      "0 4px 12px rgba(0,0,0,0.08)"

                  }}

                >

                  <h2>

                    🛠️ {
                      booking.serviceName
                    }

                  </h2>

                  <p>

                    👤 Customer:
                    {" "}
                    {
                      booking.userId?.name
                    }

                  </p>

                  <p>

                    📍 Location:
                    {" "}

                    {
                      booking.location ||
                      booking.locationDetails?.fullAddress
                    }

                  </p>

                  <p>

                    💰 Amount:
                    ₹
                    {
                      booking.servicePrice
                    }

                  </p>

                  <p>

                    📌 Status:
                    {" "}

                    <strong>

                      {
                        booking.status
                      }

                    </strong>

                  </p>

                  {/* ================= */}
                  {/* ACTION BUTTONS */}
                  {/* ================= */}

                  {(booking.status ===
                    "assigned" ||

                    booking.status ===
                    "pending") && (

                    <div
                      style={{
                        display: "flex",
                        gap: "10px",
                        marginTop: "15px"
                      }}
                    >

                      <button

                        onClick={() =>

                          providerAction(
                            booking._id,
                            "accept"
                          )

                        }

                        style={{

                          background:
                            "#10B981",

                          color: "#fff",

                          border: "none",

                          padding:
                            "10px 16px",

                          borderRadius:
                            "10px",

                          cursor:
                            "pointer"

                        }}

                      >

                        Accept

                      </button>

                      <button

                        onClick={() =>

                          providerAction(
                            booking._id,
                            "reject"
                          )

                        }

                        style={{

                          background:
                            "#EF4444",

                          color: "#fff",

                          border: "none",

                          padding:
                            "10px 16px",

                          borderRadius:
                            "10px",

                          cursor:
                            "pointer"

                        }}

                      >

                        Reject

                      </button>

                    </div>

                  )}

                  {booking.status === 'accepted' && (
                    <div style={{ marginTop: 12 }}>
                      <button onClick={() => setActiveSession(booking)} style={{ background: '#2563EB', color: '#fff', border: 'none', padding: '10px 16px', borderRadius: '10px', cursor: 'pointer' }}>Open Session</button>
                    </div>
                  )}

                </div>

              )
            })}

            </div>

          </div>

        )}

      </div>

    </div>

  );

}
